    }

    public void ShowDamageIndicator(Vector3 damageDirection)
    {
        if (damageIndicator != null && playerCamera != null)
        {
            // Calculate the angle between the camera’s forward direction and the damage direction in local space
            Vector3 forward = playerCamera.transform.forward;
            //forward.y = 0; // Optional: Flatten the forward vector if you’re only interested in horizontal plane
            Vector3 localDamageDirection = playerCamera.transform.InverseTransformDirection(damageDirection.normalized);
            localDamageDirection.y = 0; // Optional: Flatten the damage direction as well

            float angle = Mathf.Atan2(localDamageDirection.x, localDamageDirection.z) * Mathf.Rad2Deg;

            // Define the distance from the center of the screen to position the indicator
            float indicatorDistance = 400f; // Adjust this value based on your UI layout

            // Calculate the position on the canvas circle based on the angle
            float xPosition = indicatorDistance * Mathf.Sin(angle * Mathf.Deg2Rad);
            float yPosition = indicatorDistance * Mathf.Cos(angle * Mathf.Deg2Rad);

            // Update the position of the damage indicator using anchoredPosition for UI elements
            damageIndicator.rectTransform.anchoredPosition = new Vector2(xPosition, yPosition);

            // Rotate the indicator to point towards the center (opposite direction of the damage)
            damageIndicator.rectTransform.localRotation = Quaternion.Euler(0, 0, angle);



            // Make the indicator visible
            damageIndicator.gameObject.SetActive(true);

            // Hide the indicator after a short delay
