g.setColor(dot.color);
g.fillOval(dot.x, dot.y, dot.size, dot.size);
}
}

@Override
public void run() {
while (true) {
dot_movement();
dot_movement_changer();
repaint();
try {
Thread.sleep(50);
} catch (InterruptedException e) {
e.printStackTrace();
}
}
}

